// Helper functions for calendar grid
export const generateCalendarCells = (year, month, daysInMonth, firstDayOfMonth) => {
  const cells = [];

  // Add blank cells for days before the 1st of the month
  for (let i = 0; i < firstDayOfMonth; i++) {
    cells.push({ type: 'blank', day: null });
  }

  // Add cells for each day of the month
  for (let day = 1; day <= daysInMonth; day++) {
    cells.push({ type: 'day', day });
  }

  return cells;
};

export const formatMonthYear = (month, year, monthNames) => {
  return `${monthNames[month]} ${year}`;
};

// Constants
export const monthNames = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December"
];

export const dayNames = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
